head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


INSERT = 0;
UPDATE = 1;
SELECT = 2;
DELETE = 3;
NEWSEL = 4;
BZ_NEWPRE = 0; /* ELW 예비심사               */
BZ_NEWLST = 1; /* ELW 신규상장               */
BZ_ADDPRE = 2; /* ELW 추가예비               */
BZ_ADDLST = 3; /* ELW 추가상장               */
BZ_USRLST = 4; /* 신청관련 조회               */

/* 상장업무구분코드 */
CD_NEWPRE = '002'; /* ELW 예비심사               */
CD_NEWLST = '003'; /* ELW 신규상장               */
CD_ADDPRE = '004'; /* ELW 추가예비               */
CD_ADDLST = '005'; /* ELW 추가상장               */

/* 상장처리상태코드 */
/* 00 : 신청중 , 01 : 신청완료 , 10 : 접수 , 02 : 반송  */
CD_STAT_ING = '00';
CD_STAT_FIN = '01';
CD_STAT_REJ = '02'; /* 업무 처리 번호 있더라도 신규처리 */

LD_MKT_TP_CD = '1'; /* 상장공시시장구분코드 */
/* 유가 , 코스닥 시장 구분 : 일단은 유가만 신청 : 1 */


IDX_LIST = 0; /* 상장처리현황 */
IDX_MST = 1; /* ELW심사및신규상장         */
IDX_FNC = 2; /* ELW재무                   */
IDX_DRV = 3; /* ELW장외파생               */
IDX_PACK = 4; /* ELW일괄신고서             */
IDX_LP = 5; /* ELW예비심사유동성공급자   */
IDX_ULY = 6; /* ELW예비심사기초자산       */
IDX_ATTACH = 7; /* ELW첨부                   */
IDX_PUBOFR = 8; /* ELW공모사항               */
IDX_USER = 9; /* ELW 신청인정보              */
IDX_MSTADD = 10; /* ELW 추가상장              */
IDX_LPADD = 11; /* ELW 추가상장 최초조회 : 예비심사유동성공급자    */
IDX_PBCT = 12; /* ELW 추가상장 : 발행제비용의내역    */

/**
 * @method
 * @name fn_ElwPageSearch
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ElwPageSearch = function() {
    if (form.isuNm != undefined) {
        form.isuNm.setValue("");
    }
    form.action = '/list/elwPage.do';
    form.method.setValue('elwPageSearch');
    form.submit();
};
/**
 * @method
 * @name fn_ElwPageUsrSearch
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ElwPageUsrSearch = function() {
    form.bzCd.setValue(scwin.BZ_USRLST);
    if (form.isuNm != undefined) {
        form.isuNm.setValue("");
    }
    form.action = '/list/elwPage.do';
    form.method.setValue('elwPageSearch');
    form.submit();
};
/**
 * @method
 * @name fn_ElwSub
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ElwSub = function() {
    //	alert("fn_ElwSub  ==  " + bzProcsNo);
    if (scwin.isNotAdmin()) {
        if (eval(form["billLstSaveStatCd"].getValue()) != 4) {
            alert("신청인정보  페이지까지 입력을 하셔야만 제출 하실수 있습니다.");
            return;
        }

        //-- 기준가격,행사가격 데이타 검증 --> 
        if (!scwin.fn_chkSaveElwPrc()) return;
        form["listProcsStatCd"].setValue(scwin.CD_STAT_FIN); /* 상장처리상태코드 */

        if (!scwin.fn_isProcess('S')) return;
        form.action = '/list/elwPage.do';
        form.method.setValue('elwPageSub');
        form.submit();
    }
};
/**
 * @method
 * @name fn_ElwSelectSub
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ElwSelectSub = function() {
    if (scwin.isNotAdmin()) {
        if (!$("[name='checkSub']").is(':checked')) {
            alert('선택된 항목이 없습니다.');
            return;
        }
        var values = new Array();
        $("input:checkbox[name='checkSub']").each(function() {
            if (this.checked) {
                values.push($(this).val());
            }
        });
        var str;
        for (var i = 0; i < values.length; i++) {
            if (i == 0) {
                str = values[i];
            } else {
                str = str + "_" + values[i];
            }
        }
        form["listProcsStatCd"].setValue(scwin.CD_STAT_FIN); /* 상장처리상태코드 */
        form["checkSubNo"].setValue(str);
        if (!scwin.fn_isProcess('S')) return;
        form.action = '/list/elwPage.do';
        form.method.setValue('elwSelectSub');
        form.submit();
    }
};
/**
