};



//관리자인경우는 조회만 가능
/**
 * @method
 * @name isNotAdmin
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNotAdmin = function() {
    if (form.isurCd.getValue() == "99999" || form.isurCd.getValue() == "") {
        alert("\n 관리자는 조회가 가능합니다.");
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_isPossibleSave
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isPossibleSave = function() {
    scwin.isNotAdmin();

    // BZ_ADDPRE 중  '00' , '02' 만 저장가능
    // 2012/08/08 KBoY 반송시 해당탭으로 이동하기 위해 반송시 기존꺼 02로 돌리고 03으로 하나를 카피 뜨기 때문에 02로 올 일이 없다.
    if (form.bzCd.getValue() == scwin.BZ_ADDPRE || form.bzCd.getValue() == scwin.BZ_ADDLST) {
        if (form.listProcsStatCd.getValue() != "" && form.listProcsStatCd.getValue() != scwin.CD_STAT_ING && form.listProcsStatCd.getValue() != '03') {
            alert("\n 해당 종목이 처리중입니다.       \n\n 목록에서 상태를 확인하세요.");
            return false;
        }
    }

    // 반송된 업무처리일경우는 첫페이지에서만 저장이 가능 2012-07-31 KBoY 03으로 오기 때문에 앞으로 여기 올일 없음.
    if (form.listProcsStatCd.getValue() == scwin.CD_STAT_REJ) {
        if (eval(form.nowPage.getValue()) == 1) {
            form["bzProcsNo"].setValue("");
            form["transKind"].setValue(scwin.INSERT);
            form["listProcsStatCd"].setValue(scwin.CD_STAT_ING); /* 상장처리상태코드 */

            return true;
        } else {
            alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 증권발행개요 탭으로 이동후, 저장을 하세요");
            return false;
        }
    }

    //3단계(파일첨부) 입력안해도 다음단계로 이동가능하도록 수정 (2010-02-01) 
    if (form.billLstSaveStatCd.getValue() < 2) {
        if (eval(form.nowPage.getValue()) > (eval(form.billLstSaveStatCd.getValue()) + 1)) {
            alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 탭별로 작성후 저장하셔야 합니다..");
            return false;
        }
    }
    //2012-07-31 KBoY 다시 저장할때 prelistBizImpl doChangeListPorcsStatCd()에서 '03'받아다 00으로 강제 세팅함...					
    if (form.listProcsStatCd.getValue() != '03') {
        form["listProcsStatCd"].setValue(scwin.CD_STAT_ING); /* 상장처리상태코드 */

    }

    //viewFormNameAndData(); 
    if (form["bzProcsNo"].getValue() == "") form["transKind"].setValue(scwin.INSERT);

    else form["transKind"].setValue(scwin.UPDATE);
    return true;
};
/**
 * @method
 * @name fn_ElwChangePage
 * @description desc
 * @param {string} pageIndex desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ElwChangePage = function(pageIndex) {
    if (form.billLstSaveStatCd.getValue() == "") {
        form.billLstSaveStatCd.setValue(0);
    }

    //alert("현재 단계: " + pageIndex + "_최종저장단계: " + form.billLstSaveStatCd.value);

    //3단계(파일첨부) 입력안해도 다음단계로 이동가능하도록 수정 (2010-02-01)
    //상장&추가상장예비심사의경우 파일첨부 필수임 KBoY(2012-08-21)
    var bzCd = form.bzCd.getValue();
    if (eval(pageIndex) <= (eval(form.billLstSaveStatCd.getValue()) + 1)) {
        scwin.goNextPage(pageIndex);
    } else {
        //		if(form.billLstSaveStatCd.value < 3 && (bzCd == '0' || bzCd == '2')) {
        if (form.billLstSaveStatCd.getValue() < 2) {
            alert("현재페이지의 항목들을 저장후에 다음 페이지로 이동할수 있습니다.");
            return;
        } else {
            //체크안하고 페이지 자유롭게 이동
            //2012-09-04 KBoY 모든 단계에서 파일첨부 필수처리 해제 		
            /*			if(bzCd == '0' || bzCd == '2') {
            				alert("현재페이지의 항목들을 저장후에 다음 페이지로 이동할수 있습니다.");
            				return ;
            			}else{
            				goNextPage(pageIndex);
            			}
            */
            scwin.goNextPage(pageIndex);
        }
    }
};






/* 3단계(파일첨부) 입력안해도 다음단계로 이동가능하도록 수정 (2010-02-01) */
/**
 * @method
 * @name goNextPage
 * @description desc
 * @param {string} pageIndex desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.goNextPage = function(pageIndex) {
    form.nowPage.setValue(pageIndex);
    var procsStatCd = form.listProcsStatCd.getValue();
    if (form.bzProcsNo.getValue() == "") {
        // 신규 작성일경우
        form["transKind"].setValue(scwin.NEWSEL);
    } else {
        if (eval(form.nowPage.getValue()) <= eval(form.billLstSaveStatCd.getValue())) {
            // 		if( procsStatCd != '' ) {
            form["transKind"].setValue(scwin.SELECT);
        } else {
            form["transKind"].setValue(scwin.NEWSEL);
        }
    }
    scwin.fn_clearTransTbl();
    if (pageIndex == '1') {
        scwin.fn_setMainPage();
    } else if (pageIndex == '2') {
        form["transTbl"][0].setValue(scwin.IDX_FNC);
        form["transTbl"][1].setValue(scwin.IDX_DRV);
    } else if (pageIndex == '3') {
        form["transTbl"][0].setValue(scwin.IDX_ATTACH);
    } else if (pageIndex == '4') {
        form["transTbl"][0].setValue(scwin.IDX_USER);
    }
    form.action = '/list/elw.do';
    form.method.setValue('searchElw');
    form.submit();
};
/**
 * @method
 * @name fn_clearTransTbl
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_clearTransTbl = function() {
    for (var i = 0; i < form["transTbl"].length; i++) {
        form["transTbl"][i].setValue(0);
    }
};
/**
 * @method
 * @name fn_setBzCd
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setBzCd = function() {
    if (form.listBzTpCd.getValue() == scwin.CD_NEWPRE) form["bzCd"].setValue(scwin.BZ_NEWPRE);

    else if (form.listBzTpCd.getValue() == scwin.CD_NEWLST) form["bzCd"].setValue(scwin.BZ_NEWLST);

    else if (form.listBzTpCd.getValue() == scwin.CD_ADDPRE) form["bzCd"].setValue(scwin.BZ_ADDPRE);

    else if (form.listBzTpCd.getValue() == scwin.CD_ADDLST) form["bzCd"].setValue(scwin.BZ_ADDLST);
};
/**
 * @method
 * @name fn_setMainPage
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setMainPage = function() {
    if (form["bzCd"].getValue() == scwin.BZ_NEWPRE) {
        form["transTbl"][0].setValue(scwin.IDX_MST);
        form["transTbl"][1].setValue(scwin.IDX_ULY);
        form["transTbl"][2].setValue(scwin.IDX_PACK);
        form["transTbl"][3].setValue(scwin.IDX_LP);
    } else if (form["bzCd"].getValue() == scwin.BZ_NEWLST) {
        form["transTbl"][0].setValue(scwin.IDX_MST);
        form["transTbl"][1].setValue(scwin.IDX_ULY);
        form["transTbl"][2].setValue(scwin.IDX_PUBOFR);
        form["transTbl"][3].setValue(scwin.IDX_LP);
    } else if (form["bzCd"].getValue() == scwin.BZ_ADDPRE) {
        form["transTbl"][0].setValue(scwin.IDX_MSTADD);
        form["transTbl"][1].setValue(scwin.IDX_PACK);
        form["transTbl"][2].setValue(scwin.IDX_ULY);
        form["transTbl"][3].setValue(scwin.IDX_LPADD);
        form["transTbl"][4].setValue(scwin.IDX_LP);
    } else if (form["bzCd"].getValue() == scwin.BZ_ADDLST) {
        form["transTbl"][0].setValue(scwin.IDX_MSTADD);
        form["transTbl"][1].setValue(scwin.IDX_PUBOFR);
        form["transTbl"][2].setValue(scwin.IDX_ULY);
        form["transTbl"][3].setValue(scwin.IDX_LPADD);
        form["transTbl"][4].setValue(scwin.IDX_LP);
    }
};
openCalendarObj = null;
paramCalendarObj = null;
/**
 * @method
