    scwin.paramCalendarObj = paramObj;
    if (chkBzCalnd) {
        isChkBzCalnd = true;
    } else {
        isChkBzCalnd = false;
    }
    popUpYYYYMMDD(obj);
};
/**
 * @method
 * @name fn_IsValid
 * @description desc
 * @param {string} obj desc
 * @param {string} arrVar desc
 * @param {string} arrVarAlt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValid = function(obj, arrVar, arrVarAlt) {
    for (i = 0; i < arrVar.length; i++) {
        var arrObj = obj[arrVar[i]];
        if (arrObj.getValue() == '' || arrObj.getValue() == ' ') {
            var msg = arrObj.alt != '' ? arrObj.alt : arrVarAlt[i];
            alert(msg + '(은)는 반드시 입력하셔야 합니다.');
            arrObj.focus();
            return false;
        }
    }
    return true;
};
/**
 * @method
 * @name fn_IsValidArr
 * @description desc
 * @param {string} obj desc
 * @param {string} arrVar desc
 * @param {string} arrVarAlt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValidArr = function(obj, arrVar, arrVarAlt) {
    for (i = 0; i < arrVar.length; i++) {
        var arrObj = obj[arrVar[i]];
        for (j = 0; j < arrObj.length; j++) {
            if (arrObj[j].getValue() == '') {
                alert(arrVarAlt[i] + '(은)는 반드시 입력하셔야 합니다.');
                arrObj[j].focus();
                return false;
            }
        }
    }
    return true;
};
/**
 * @method
 * @name fn_IsValidDate
 * @description desc
 * @param {string} obj desc
 * @param {string} arrVar desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValidDate = function(obj, arrVar) {
    for (i = 0; i < arrVar.length; i++) {
        var arrObj = obj[arrVar[i]];
        if (arrObj.getValue() == '') {
            alert(arrObj.alt + '(은)는 반드시 입력하셔야 합니다.');
            arrObj.focus();
            return false;
        }
        if (arrObj.getValue().length != 8) {
            alert(arrObj.alt + '입력 날짜를 확인하세요');
            arrObj.focus();
            return false;
        }
    }
    return true;
};
/**
 * @method
 * @name fn_IsValidArrDate
 * @description desc
 * @param {string} obj desc
 * @param {string} arrVar desc
 * @param {string} checkLen desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValidArrDate = function(obj, arrVar, checkLen) {
    for (i = 0; i < arrVar.length; i++) {
        var arrObj = obj[arrVar[i]];
        for (j = 0; j < arrObj.length; j++) {
            if (arrObj[j].getValue() == '' || arrObj[j].getValue().length != checkLen) {
                alert('입력 날짜를 확인하세요');
                arrObj[j].focus();
                return false;
            }
        }
    }
    return true;
};
/**
 * @method
 * @name fn_IsValidSelect
 * @description desc
 * @param {string} obj desc
 * @param {string} arrVar desc
 * @param {string} arrVarAlt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValidSelect = function(obj, arrVar, arrVarAlt) {
    for (i = 0; i < arrVar.length; i++) {
        var arrObj = obj[arrVar[i]];
        if (arrObj.getValue() == '') {
            alert(arrVarAlt[i] + '(은)는 반드시 선택하셔야 합니다.');
            arrObj.focus();
            return false;
        }
    }
    return true;
};


// 숫자와 "." 만 포함되어있는지 Check
/**
 * @method
 * @name Chk_Digit_Point
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Digit_Point = function(str) {
    for (var i = 0; i < str.length; i++) {
        var ch = str.charAt(i);
        if ((ch < "0" || ch > "9") && !(ch == "." || ch == ",")) {
            return false;
        }
    }
    return true;
};

// 만기상환률 : 숫자와 "." 만 포함되어있는지 Check 숫자와 '.' 만 가능, 999 보다 크면 false
/**
 * @method
 * @name Chk_Sosu_Point_1
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Sosu_Point_1 = function(Name) {
    if (!scwin.Chk_Digit_Point(Name.getValue())) {
        alert(" 숫자와 . 만 입력 가능합니다.");
        Name.focus();
        return false;
    }
    var temp = Name.getValue().replace(",", "");
    if (temp >= 10000) {
        alert(" 10000보다 작아야 합니다.");
        Name.focus();
        return false;
    }
    return true;
};
/**
 * @method
 * @name Chk_Sosu_Point_Digit
 * @description desc
 * @param {string} Name desc
 * @param {string} funcName desc
 * @param {string} digit desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Sosu_Point_Digit = function(Name, funcName, digit) {
    if (funcName == "Chk_Sosu_Point_1") {
        scwin.Chk_Sosu_Point_1(Name);
    } else if (funcName == "Chk_Sosu_Point_2") {
        scwin.Chk_Sosu_Point_2(Name);
    } else if (funcName == "Chk_Sosu_Point_Final_Pay_Amt") {
        scwin.Chk_Sosu_Point_Final_Pay_Amt(Name);
    } else if (funcName == "fn_showMsgForRemind") {
        scwin.fn_showMsgForRemind(Name.alt, Name.getValue());
    } else if (funcName == "Chk_Percent") {
        scwin.Chk_Percent(Name);
    }
    var arrVal = Name.getValue().split(".");
    if (arrVal[1].length > digit) {
        alert(Name.alt + "는(은) 소수점 이하 " + digit + "자리까지 입력 가능합니다.");
        Name.focus();
        return false;
    }
};
/**
 * @method
 * @name Chk_Sosu_Point_Final_Pay_Amt
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Sosu_Point_Final_Pay_Amt = function(Name) {
    if (!scwin.Chk_Digit_Point(Name.getValue())) {
        alert(" 숫자와 . 만 입력 가능합니다.");
        Name.focus();
        return false;
    }
    if (Name.getValue() >= 100000) {
        alert("만원단위까지 입력이 가능합니다.");
        Name.focus();
        return false;
    }
    return true;
};

// 백분율 Check (0 ~ 100), 소수점과 '.' 만 가능
/**
 * @method
 * @name Chk_Percent
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Chk_Percent = function(Name) {
    if (!scwin.Chk_Digit_Point(Name.getValue())) {
        alert(" 숫자와 . 만 입력 가능합니다.");
        Name.focus();
        return false;
    }
    if (Name.getValue() > 100) {
        alert(" 100보다 큽니다.");
        Name.focus();
        return false;
    }
    return true;
};

