/*
 * 상장업무처리 메세지 처리
 */
LastJob = "";
/**
 * @method
 * @name fn_isProcess
 * @description desc
 * @param {string} gubun desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isProcess = function(gubun) {
    if (gubun == 'I') scwin.LastJob = '저장';

    else if (gubun == 'U') scwin.LastJob = '수정';

    else if (gubun == 'D') scwin.LastJob = '삭제';

    else if (gubun == 'S') scwin.LastJob = '제출';
    if (!window.confirm("[" + scwin.LastJob + "] 하시겠습니까?")) {
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_msgResultForSave
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_msgResultForSave = function() {
    if (form.resultMsg.getValue() != "") alert(form.resultMsg.getValue());
};
/**
 * @method
 * @name fn_showMsgForRemind
 * @description desc
 * @param {string} msg desc
 * @param {string} value desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_showMsgForRemind = function(msg, value) {
    alert(msg + "  :  " + value + "  으로 입력하셨습니다.");
};
/**
 * @method
 * @name fn_chkElwPrc
 * @description desc
 * @param {string} msg desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkElwPrc = function(msg, obj) {
    var val = obj.getValue();
    if (val == '0') {
        alert(msg + " 항목은 0으로 입력할 수 없습니다.");
        obj.setValue('');
        obj.focus();
        return false;
    } else if (val != '') {
        scwin.fn_showMsgForRemind(msg, val);
        return true;
    }
};
/**
 * @method
 * @name fn_chkSaveElwPrc
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_chkSaveElwPrc = function() {
    if (form.elwUlyBasPrc != undefined && form.elwUlyBasPrc.getValue() == 0) {
        alert("기준가격/지수 항목은 0인 값을 입력할 수 없습니다.");
        form.elwUlyBasPrc.focus();
        return false;
    }
    if (form.elwExerPrc != undefined && form.elwExerPrc.getValue() == 0) {
        alert("행사가격/지수 항목은 0인 값을 입력할 수 없습니다.");
        form.elwExerPrc.focus();
        return false;
    }
    return true;
};
